-- Phase 3: requirements per stage. One row per applicant and requirement holds its current
-- state; every change is also written to the append-only applicant_stage_histories, and the
-- files live in documents (private bucket). Additive only.
create table if not exists public."applicant_requirements" (
  "id" bigint generated by default as identity primary key,
  "applicant_id" bigint not null references public."applicants" ("id") on delete cascade,
  "requirement_key" text not null,
  "stage" text not null,
  "status" text not null default 'pending',
  "data" jsonb not null default '{}'::jsonb,
  "submitted_by_user_id" bigint references public."users" ("id") on delete set null,
  "submitted_at" timestamptz,
  "reviewed_by_user_id" bigint references public."users" ("id") on delete set null,
  "reviewed_at" timestamptz,
  "return_reason" text,
  "created_at" timestamptz default now(),
  "updated_at" timestamptz default now(),
  constraint "applicant_requirements_status_check" check ("status" in ('pending', 'submitted', 'accepted', 'returned')),
  constraint "applicant_requirements_unique" unique ("applicant_id", "requirement_key")
);
create index if not exists "applicant_requirements_applicant_idx" on public."applicant_requirements" ("applicant_id");
alter table public."applicant_requirements" enable row level security;
create trigger set_updated_at before update on public."applicant_requirements" for each row execute function public.set_updated_at();

-- The LOI requirement is read from the LOI record; Admin can now return it with a reason.
alter table public."applicants" add column if not exists "loi_returned_at" timestamptz;
alter table public."applicants" add column if not exists "loi_returned_by_user_id" bigint;
alter table public."applicants" add column if not exists "loi_return_reason" text;
alter table public."applicants" add constraint "applicants_loi_returned_by_fkey"
  foreign key ("loi_returned_by_user_id") references public."users" ("id") on delete set null;
